-- Recetario: recetas del profe (una sola lista para todos los alumnos con nutrición activa).
-- Ingredientes por nombre/estado de la base alimentos.js; macros se calculan en la app.
create table if not exists public.recetario (
  id text primary key,
  nombre text not null check (char_length(nombre) <= 80),
  emoji text not null default '🍽️',
  comidas text[] not null default '{}',            -- desayuno, almuerzo, once, cena, snack
  minutos int,
  items jsonb not null default '[]'::jsonb,        -- [{n, e, g}] para 1 porción
  pasos text[] not null default '{}',
  activo boolean not null default true,
  orden int not null default 0,
  updated_at timestamptz not null default now()
);
alter table public.recetario enable row level security;
drop policy if exists coach_all on public.recetario;
create policy coach_all on public.recetario for all using (public.is_coach()) with check (public.is_coach());
drop policy if exists alumno_lee on public.recetario;
create policy alumno_lee on public.recetario for select to authenticated using (
  activo and exists (select 1 from public.nutricion n where n.alumno = public.mi_codigo() and n.activo));
insert into public.recetario (id,nombre,emoji,comidas,minutos,items,pasos,orden) values
('avena-proteica','Avena proteica con plátano','🥣',array['desayuno']::text[],5,'[{"n": "Avena en hojuelas", "e": "", "g": 50}, {"n": "Leche semidescremada", "e": "", "g": 200}, {"n": "Proteína whey (polvo)", "e": "", "g": 30}, {"n": "Plátano", "e": "", "g": 100}, {"n": "Semillas de chía", "e": "", "g": 10}]'::jsonb,array['Calienta la leche con la avena 3 min.','Fuera del fuego agrega la proteína y revuelve.','Corona con plátano en rodajas y chía.']::text[],1),
('huevos-marraqueta','Huevos revueltos con marraqueta y palta','🍳',array['desayuno','once']::text[],10,'[{"n": "Huevo entero", "e": "", "g": 110}, {"n": "Pan marraqueta", "e": "", "g": 50}, {"n": "Palta", "e": "", "g": 40}, {"n": "Tomate", "e": "", "g": 60}]'::jsonb,array['Bate los huevos con sal y revuelve en sartén antiadherente.','Tuesta la marraqueta y unta la palta.','Acompaña con tomate en rodajas.']::text[],2),
('yogur-granola','Yogur griego con granola y frutillas','🍓',array['desayuno','snack']::text[],3,'[{"n": "Yogur griego natural 0%", "e": "", "g": 200}, {"n": "Granola", "e": "", "g": 30}, {"n": "Frutillas", "e": "", "g": 100}, {"n": "Miel", "e": "", "g": 10}]'::jsonb,array['Pon el yogur en un pocillo.','Agrega las frutillas picadas y la granola.','Termina con un hilo de miel.']::text[],3),
