('tostadas-pavo','Tostadas integrales con quesillo y pavo','🥪',array['desayuno','once']::text[],5,'[{"n": "Pan de molde integral", "e": "", "g": 60}, {"n": "Quesillo", "e": "", "g": 60}, {"n": "Jamón de pavo", "e": "", "g": 40}, {"n": "Tomate", "e": "", "g": 60}]'::jsonb,array['Tuesta el pan.','Arma con quesillo, jamón de pavo y tomate.']::text[],5),
('pollo-arroz','Pollo a la plancha con arroz y ensalada','🍗',array['almuerzo','cena']::text[],20,'[{"n": "Pechuga de pollo", "e": "cocido", "g": 150}, {"n": "Arroz blanco", "e": "cocido", "g": 160}, {"n": "Ensalada surtida (lechuga, tomate, pepino)", "e": "", "g": 150}, {"n": "Aceite de oliva", "e": "", "g": 10}]'::jsonb,array['Sazona la pechuga y cocínala a la plancha 5–6 min por lado.','Sirve con el arroz.','Aliña la ensalada con el aceite de oliva.']::text[],6),
('fajitas-pollo','Fajitas de pollo','🌯',array['almuerzo','cena']::text[],20,'[{"n": "Tortilla de trigo (wrap)", "e": "", "g": 80}, {"n": "Pechuga de pollo", "e": "cocido", "g": 120}, {"n": "Pimentón", "e": "", "g": 60}, {"n": "Cebolla", "e": "", "g": 50}, {"n": "Palta", "e": "", "g": 40}, {"n": "Aceite de oliva", "e": "", "g": 5}]'::jsonb,array['Corta pollo, pimentón y cebolla en tiras.','Saltea todo con el aceite y comino, ajo y paprika.','Rellena las 2 tortillas y agrega la palta.']::text[],7),
('fideos-bolognesa','Fideos con salsa boloñesa','🍝',array['almuerzo']::text[],25,'[{"n": "Fideos / pasta", "e": "cocido", "g": 200}, {"n": "Carne molida 5% grasa", "e": "cocido", "g": 120}, {"n": "Tomate", "e": "", "g": 100}, {"n": "Cebolla", "e": "", "g": 40}, {"n": "Queso parmesano", "e": "", "g": 10}]'::jsonb,array['Sofríe la cebolla y dora la carne.','Agrega el tomate picado y cocina 10 min.','Sirve sobre los fideos con parmesano.']::text[],8),
('salmon-papas','Salmón con papas y brócoli','🐟',array['almuerzo','cena']::text[],25,'[{"n": "Salmón", "e": "cocido", "g": 130}, {"n": "Papa", "e": "cocido", "g": 200}, {"n": "Brócoli", "e": "cocido", "g": 120}, {"n": "Aceite de oliva", "e": "", "g": 5}]'::jsonb,array['Cuece las papas en agua con sal.','Cocina el salmón al horno o sartén 10–12 min.','Brócoli al vapor 5 min y aliña con aceite de oliva.']::text[],9),
